/* @lc app=leetcode id=1998 lang=kotlin */ class Solution { fun gcdSort(nums: IntArray): Boolean = IntArray(100001) { it }.let { p -> object { fun f(i: Int): Int = if (p[i] == i) i else f(p[i]).also { p[i] = it } }.let { find -> object { fun u(i: Int, j: Int) = find.f(i).let { ri -> find.f(j).let { rj -> if (ri != rj) p[ri] = rj else Unit } } }.let { union -> nums.forEach { n -> (2..java.lang.Math.sqrt(n.toDouble()).toInt()).fold(n) { acc, d -> if (acc % d == 0) union.u(n, d).let { generateSequence(acc) { it / d }.first { it % d != 0 } } else acc }.let { if (it > 1) union.u(n, it) else Unit } }.run { nums.sortedArray().withIndex().all { (i, v) -> find.f(v) == find.f(nums[i]) } } } } } }